// Every visible word of the admin panel, in two complete sets: "es" (Spanish, pinned character
// for character by the regression suite) and "it" (Italian). src/admin.js reads the set chosen by C.adminLanguage
// through AT. Nothing here touches the structure of the page: forms, action names ("do" values), URLs and CSS classes
// stay in src/admin.js.
//
// Conventions:
//  - A plain string is text; a function builds text from numbers or plain strings. A function whose name ends in
//    "Html" returns a piece of HTML and expects its arguments ALREADY ESCAPED (src/admin.js escapes every value).
//  - Values that come from people (names, addresses, errors) are never escaped here; admin.js does that.
//
// AT.mail holds the e-mails the researcher receives (the notice of a new or cancelled booking and the test e-mail):
// src/mail.js (tplAdmin, tplTest) writes them in the admin language from here.
import { C } from "./config.js";
import { pathFor } from "./paths.js";
import { DAYS_AHEAD, SLOT_MINUTES, SESSION_MINUTES, MIN_NOTICE_HOURS, FLEX_NOTICE_MIN, SHORT_NOTICE_MIN } from "./slots.js";

// How the study is named in the subjects and titles below (studyName in site.config.js), per language.
const SN = C.studyName;
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

const pl = (n, one, many) => (n === 1 ? one : many);

// ============================================================================================================
// Spanish
// ============================================================================================================
